<script setup lang="ts">
import {computed,ref} from 'vue'
import {NButton,NInput,NModal,NSelect,NCheckbox} from 'naive-ui'
import {request} from '../api/client'
import {kinds,money,type Account,type StockAccount,type Member,type AccountBase,type AccountKind} from '../api/funds'
import AccountAvatar from '../components/AccountAvatar.vue'
import TagInput from '../components/TagInput.vue'
const props=defineProps<{mode:'accounts'|'stock-accounts';accounts:Account[];locations:StockAccount[];members:Member[];editable:boolean}>()
const emit=defineEmits<{changed:[]}>()
const show=ref(false),id=ref(''),name=ref(''),kind=ref<AccountKind>('public'),member=ref<string|null>(null),avatar=ref(''),tags=ref<string[]>([]),active=ref(true),busy=ref(false),error=ref('')
const filterKind=ref<string|null>(null),filterTag=ref<string|null>(null),filterMember=ref<string|null>(null)
const all=computed<AccountBase[]>(()=>props.mode==='accounts'?props.accounts:props.locations)
const rows=computed(()=>all.value.filter(a=>(!filterKind.value||a.kind===filterKind.value)&&(!filterTag.value||a.tags.includes(filterTag.value))&&(!filterMember.value||a.member_id===filterMember.value)))
const tagOptions=computed(()=>[...new Set(all.value.flatMap(a=>a.tags))].map(value=>({label:value,value})))
const memberOptions=computed(()=>props.members.map(m=>({label:m.name,value:m.id})))
function edit(a?:AccountBase){id.value=a?.id||'';name.value=a?.name||'';kind.value=a?.kind||'public';member.value=a?.member_id||null;avatar.value=a?.avatar_url||'';tags.value=[...(a?.tags||[])];active.value=a?.active??true;error.value='';show.value=true}
async function save(){if(busy.value)return;busy.value=true;error.value='';try{await request(`/${props.mode}${id.value?'/'+id.value:''}`,id.value?'PATCH':'POST',{name:name.value,member_id:member.value,avatar_url:avatar.value||null,tags:tags.value,active:active.value,...(!id.value?{kind:kind.value}:{})});show.value=false;emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
const custodyShow=ref(false),custodyId=ref(''),custodian=ref<string|null>(null)
function custody(a:AccountBase){custodyId.value=a.id;custodian.value=(a as StockAccount).current_custody?.member_id||null;error.value='';custodyShow.value=true}
async function saveCustody(){if(busy.value)return;busy.value=true;try{await request(`/stock-accounts/${custodyId.value}/custody`,'POST',{member_id:custodian.value});custodyShow.value=false;emit('changed')}catch(e){error.value=(e as Error).message}finally{busy.value=false}}
</script>
<template><div class="toolbar"><h2>{{mode==='accounts'?'资金账户':'货物账户'}}</h2><NButton v-if="editable" @click="edit()">新建账户</NButton></div><div class="filters"><NSelect v-model:value="filterKind" clearable placeholder="所有类型" :options="Object.entries(kinds).map(([value,label])=>({value,label}))"/><NSelect v-model:value="filterTag" clearable placeholder="所有标签" :options="tagOptions"/><NSelect v-model:value="filterMember" clearable placeholder="所有联系人" :options="memberOptions"/></div><p v-if="mode==='accounts'" class="muted">私账为正表示应交回社团，为负表示社团应偿还。</p><div class="table-wrap"><table><thead><tr><th>账户</th><th>类型</th><th>联系人</th><th>标签</th><th>{{mode==='accounts'?'余额（元）':'当前保管人'}}</th><th>状态</th><th v-if="editable">操作</th></tr></thead><tbody><tr v-for="a in rows" :key="a.id"><td><AccountAvatar :name="a.name" :url="a.avatar_url"/>{{a.name}}<small>{{a.id}}</small></td><td>{{kinds[a.kind]}}</td><td>{{a.member_name||'未绑定'}}</td><td>{{a.tags.join('，')}}</td><td>{{mode==='accounts'?money((a as Account).balance_minor):((a as StockAccount).current_custody?.member_name||'未指定')}}</td><td>{{a.active?'启用':'停用'}}</td><td v-if="editable"><NButton size="small" @click="edit(a)">编辑</NButton><NButton v-if="mode==='stock-accounts'&&a.kind!=='external'" size="small" @click="custody(a)">保管关系</NButton></td></tr></tbody></table></div><NModal v-model:show="show" preset="card" title="账户资料" class="dialog"><label>名称<NInput v-model:value="name"/></label><label>类型<NSelect v-model:value="kind" :disabled="!!id" :options="Object.entries(kinds).map(([value,label])=>({value,label}))"/></label><p v-if="id" class="muted">账户类型固定，需要其他类型时请新建账户。</p><label>联系人<NSelect v-model:value="member" clearable :options="memberOptions" placeholder="可不绑定"/></label><label>头像图片地址<NInput v-model:value="avatar" placeholder="可留空"/></label><label>标签<TagInput v-model="tags"/></label><NCheckbox v-model:checked="active">启用</NCheckbox><p class="error">{{error}}</p><NButton :loading="busy" @click="save">保存</NButton></NModal><NModal v-model:show="custodyShow" preset="card" title="当前保管成员" class="dialog"><p>保管关系独立于联系人，交接后保留历史。</p><NSelect v-model:value="custodian" clearable :options="memberOptions"/><p class="error">{{error}}</p><NButton :loading="busy" @click="saveCustody">保存</NButton></NModal></template>
